export default function MenuCard({ item, addToCart }) {
  const outOfStock = item.stock === 0;

  return (
    <div className="menu-card">
      {/* Badges */}
      <div className="menu-badges">
        {item.is_popular && (
          <span className="badge badge-popular">🔥 Popular</span>
        )}
        {item.avg_rating >= 4.5 && (
          <span className="badge badge-top">⭐ Top Rated</span>
        )}
      </div>

      {/* Main content */}
      <div className="menu-card-content">
        <h4>{item.name}</h4>

        <div className="menu-price">₹{item.price}</div>

        <div className="menu-meta">
          ⭐ {item.avg_rating || 0} | Sold: {item.sold_count || 0}
        </div>

        <div className={`menu-stock ${outOfStock ? "out" : ""}`}>
          {outOfStock ? "Out of Stock" : `Stock: ${item.stock}`}
        </div>
      </div>

      {/* Button */}
      <button
        className="add-btn"
        disabled={outOfStock}
        onClick={() => addToCart(item)}
      >
        {outOfStock ? "Unavailable" : "Add to Cart"}
      </button>
    </div>
  );
}
